    P('N-HOSTA', 'Hosta', ['outdoor-plants'], 11, 'Big blue-green leaves for shade. Watch for slugs. A 2 litre pot with three to five leaves. It dies down in winter and returns bigger each spring.', 'a hosta plant with large blue green leaves in a pot', attributes=dict(light='Shade', hardiness='Hardy', pot_size='17 cm', material='Terracotta')),
