    P('N-TOMATO-SEED', 'Tomato seed, Costoluto', ['seeds'], 3.5, 'A ribbed beefsteak from our own seed bed. Forty seeds. Sow indoors in March and plant out after the last frost. Big, ribbed fruit from August.', 'a small paper seed packet with an illustration of a ribbed red tomato', attributes=dict(light='Full sun', hardiness='Tender', pot_size='', material='')),
    P('N-BEAN-SEED', 'Climbing bean seed', ['seeds'], 3, 'A purple-podded climbing bean that turns green when cooked. Fifty seeds. Sow in May, straight in the ground, beside a cane wigwam. Pick young for the best pods.', 'a small paper seed packet with an illustration of purple beans', attributes=dict(light='Full sun', hardiness='Half hardy', pot_size='', material='')),
    P('N-LETTUCE-SEED', 'Lettuce mix seed', ['seeds'], 2.5, 'Six cut-and-come-again lettuces in one packet. Sow a short row every fortnight from March. Cut the outer leaves and the plant keeps growing.', 'a small paper seed packet with an illustration of lettuce leaves', attributes=dict(light='Part shade', hardiness='Hardy', pot_size='', material='')),
    P('N-SWEET-PEA', 'Sweet pea seed', ['seeds'], 3, 'A scented old mix in every colour. Soak overnight. Sow in autumn or early spring and give them something to climb. Pick daily to keep them flowering.', 'a small paper seed packet with an illustration of sweet pea flowers', attributes=dict(light='Full sun', hardiness='Hardy', pot_size='', material='')),
    P('N-WILDFLOWER', 'Wildflower mix', ['seeds'], 6, 'Twenty native wildflowers for a square metre of bees. Sow on bare soil in spring or autumn and do not feed it. Flowers from the second month.', 'a paper seed packet with an illustration of mixed wildflowers', attributes=dict(light='Full sun', hardiness='Hardy', pot_size='', material='')),
    P('N-TULIP-BULBS', 'Tulip bulbs, 12', ['seeds'], 9, 'A dozen dark tulips for pots and borders. Plant in November. Twelve large bulbs of one dark variety. Plant them 15 cm deep in November.', 'a dozen tulip bulbs in a paper bag', axis='pot_size', values=['9 cm'], attributes=dict(light='Full sun', hardiness='Hardy', material='')),
    P('N-DAFFODIL-BULBS', 'Daffodil bulbs, 25', ['seeds'], 12, 'Small early daffodils that come back every year. Twenty-five bulbs of a small early variety for pots and grass. They multiply each year.', 'a pile of daffodil bulbs in a paper bag', attributes=dict(light='Part shade', hardiness='Hardy', pot_size='', material='')),
    P('N-GARLIC', 'Seed garlic, 3 bulbs', ['seeds'], 7, 'Hardneck garlic to plant in autumn and lift in July. Three hardneck bulbs, about thirty cloves. Plant the cloves in October, 15 cm apart.', 'three bulbs of seed garlic in a paper bag', attributes=dict(light='Full sun', hardiness='Hardy', pot_size='', material='')),
    P('N-TERRACOTTA', 'Terracotta pot', ['pots'], 8, 'A frost-proof terracotta pot with a drainage hole and a saucer. Fired at a high temperature, so it survives winter outside. Available in three sizes.', 'a plain terracotta pot with a saucer', axis='pot_size', values=['12 cm', '17 cm', '21 cm', '30 cm'], attributes=dict(light='', hardiness='', material='Terracotta')),
    P('N-GLAZED-POT', 'Glazed stoneware pot', ['pots'], 24, 'A reactive-glazed pot for indoors, with a hole. Each pot comes out of the kiln slightly different. The drainage hole and a saucer are included.', 'a {value} glazed stoneware plant pot', axis='color', values=['Green', 'White', 'Blue'], picture_per_value=True, attributes=dict(light='', hardiness='', pot_size='17 cm', material='Ceramic')),
    P('N-ZINC-PLANTER', 'Zinc trough', ['pots'], 45, 'A 60 cm zinc trough for herbs on a windowsill. Galvanised steel with drainage holes and a tray. It holds four herb pots in a row.', 'a long zinc metal planter trough', attributes=dict(light='', hardiness='', pot_size='30 cm', material='Stainless steel', dimensions='60 x 20 x 20 cm')),
    P('N-HANGING-POT', 'Hanging pot', ['pots'], 22, 'A stoneware pot on a jute hanger. A stoneware pot with a drainage plug and a jute hanger of 90 cm. Good for a trailing plant.', 'a stoneware hanging plant pot on a jute macrame hanger', attributes=dict(light='', hardiness='', pot_size='17 cm', material='Ceramic')),
    P('N-SEED-TRAY', 'Seed trays, set of 3', ['pots', 'seeds'], 12, 'Three rigid recycled trays with lids. Rigid trays that last years, with clear lids for the first weeks. They stack when empty.', 'three black seed trays with clear lids stacked', attributes=dict(light='', hardiness='', pot_size='', material='Recycled polyester')),
    P('N-RAISED-BED', 'Oak raised bed', ['pots', 'furniture'], 190, 'A 120 by 80 cm raised bed in oak sleepers, no tools needed. Oak sleepers that slot together without screws. Fill it with about 200 litres of compost.', 'a rectangular oak raised garden bed', attributes=dict(light='', hardiness='', pot_size='', material='Oak', dimensions='120 x 80 x 40 cm')),
    P('N-COMPOST', 'Peat-free compost, 40 l', ['pots'], 9, 'Our own mix for pots and beds. Bark, coir and green compost, with slow-release feed for six weeks. A 40 litre bag fills four large pots.', 'a plain kraft paper bag of compost', attributes=dict(light='', hardiness='', pot_size='', material='')),
    P('N-SPADE', 'Forged spade', ['tools'], 75, 'A forged steel spade with an ash handle, sharpened before it ships. A narrow blade with a tread, forged from one piece of steel. It comes with a twenty-year guarantee.', 'a garden spade with a steel blade and an ash wood handle', attributes=dict(light='', hardiness='', pot_size='', material='Stainless steel')),
    P('N-FORK', 'Forged fork', ['tools'], 75, 'A four-tine fork that does not bend. Forged tines and an ash handle with a wide grip. It lifts potatoes and turns compost without bending.', 'a garden fork with steel tines and an ash handle', attributes=dict(light='', hardiness='', pot_size='', material='Stainless steel')),
    P('N-TROWEL', 'Hand trowel', ['tools'], 22, 'A stainless trowel with an ash handle. A narrow blade for planting and a wide one for potting, both stainless. The handle is oiled ash.', 'a stainless steel hand trowel with a wooden handle', attributes=dict(light='', hardiness='', pot_size='', material='Stainless steel')),
    P('N-SECATEURS', 'Bypass secateurs', ['tools'], 48, 'Forged bypass secateurs with a replaceable blade. Forged from steel, with a blade that unscrews for sharpening or replacing. They cut branches up to 20 mm.', 'a pair of red handled bypass secateurs', attributes=dict(light='', hardiness='', pot_size='', material='Stainless steel')),
    P('N-WATERING-CAN', 'Watering can', ['tools'], 38, 'A 5 litre galvanised can with a brass rose. Galvanised steel with a long spout and a fine brass rose that unscrews. Balanced to pour with one hand.', 'a {value} galvanised metal watering can', axis='color', values=['Silver', 'Green'], picture_per_value=True, attributes=dict(light='', hardiness='', pot_size='', material='Stainless steel')),
    P('N-GLOVES', 'Leather gloves', ['tools'], 18, 'Goatskin gloves that let you feel a seedling. Soft goatskin with a cotton back, in three sizes. Thorns do not get through.', 'a pair of tan leather gardening gloves', axis='size', values=['S', 'M', 'L'], attributes=dict(light='', hardiness='', pot_size='', material='Leather')),
    P('N-HOE', 'Dutch hoe', ['tools'], 42, 'A push hoe for weeds between rows. A sharp blade on a 150 cm ash handle. Walk backwards and the weeds are gone.', 'a long handled dutch hoe', attributes=dict(light='', hardiness='', pot_size='', material='Stainless steel')),
    P('N-KNEELER', 'Kneeling pad', ['tools'], 14, 'A thick foam pad for beds and borders. Thick closed-cell foam that does not soak up water. It hangs on a hook by a loop.', 'a green foam garden kneeling pad', attributes=dict(light='', hardiness='', pot_size='', material='Rubber')),
    P('N-TOOL-SET', 'Hand tool set', ['tools'], 55, 'Trowel, fork and dibber in a canvas roll. Three stainless tools with ash handles in a canvas roll. A good first set or a good gift.', 'a hand trowel, a hand fork and a dibber in a canvas roll', attributes=dict(light='', hardiness='', pot_size='', material='Stainless steel')),
    P('N-BENCH', 'Oak garden bench', ['furniture'], 390, 'A 150 cm oak bench that greys outside and lasts decades. Solid oak, joined with oak pegs and stainless screws. Leave it to silver or oil it once a year.', 'a solid oak garden bench', attributes=dict(light='', hardiness='', pot_size='', material='Oak', dimensions='150 x 55 x 85 cm')),
    P('N-BISTRO-SET', 'Bistro set', ['furniture'], 220, 'A folding steel table and two chairs for a balcony. Powder-coated steel that folds flat against a wall. The table is 60 cm across.', 'a {value} folding steel bistro table with two chairs', axis='color', values=['Green', 'Black', 'White'], picture_per_value=True, attributes=dict(light='', hardiness='', pot_size='', material='Stainless steel', dimensions='60 cm table')),
    P('N-DECK-CHAIR', 'Deck chair', ['furniture'], 85, 'A beech deck chair with a striped canvas seat. Oiled beech with a canvas seat that unclips for washing. It folds flat for winter.', 'a wooden deck chair with a striped canvas seat', attributes=dict(light='', hardiness='', pot_size='', material='Oak')),
    P('N-PARASOL', 'Parasol', ['furniture'], 140, 'A 2.5 m parasol with an ash pole and a canvas cover. A 2.5 m canopy on an ash pole with a brass tilt joint. The base is sold separately.', 'a large canvas garden parasol with a wooden pole', axis='color', values=['Oatmeal', 'Green'], picture_per_value=True, attributes=dict(light='', hardiness='', pot_size='', material='Cotton')),
    P('N-FIRE-BOWL', 'Steel fire bowl', ['furniture'], 160, 'A 70 cm steel fire bowl that rusts to a warm brown. Three millimetre steel on a tripod stand. It arrives grey and turns brown in a month outside.', 'a round rusted steel fire bowl', attributes=dict(light='', hardiness='', pot_size='', material='Stainless steel', dimensions='70 cm')),
    P('N-POTTING-BENCH', 'Potting bench', ['furniture', 'tools'], 240, 'A pine potting bench with a zinc top and a shelf. A zinc top that wipes clean and a shelf for pots. Assembly takes twenty minutes.', 'a wooden potting bench with a zinc top', attributes=dict(light='', hardiness='', pot_size='', material='Oak', dimensions='120 x 50 x 90 cm')),
    P('N-STARTER-KIT', 'Kitchen garden kit', ['seeds', 'tools'], 45, 'Tomato, bean and lettuce seed, three trays and a trowel. Everything for a first season of vegetables in one box. The instructions fit on one card.', 'seed packets, seed trays and a trowel arranged together', grouped=['N-TOMATO-SEED', 'N-BEAN-SEED', 'N-LETTUCE-SEED', 'N-SEED-TRAY', 'N-TROWEL'], attributes=dict(light='', hardiness='', pot_size='', material='')),
    P('N-SHADE-SET', 'Shady corner set', ['outdoor-plants'], 34, 'A hardy fern, a hosta and a bag of compost. Two plants that thrive where nothing else will, with the compost to plant them. For a north-facing corner.', 'a fern and a hosta in pots beside a bag of compost', grouped=['N-FERN-OUTDOOR', 'N-HOSTA', 'N-COMPOST'], attributes=dict(light='Shade', hardiness='Hardy', pot_size='', material='')),
    P('N-GIFT-CARD', 'Greenhaven gift card', ['pots'], 40, 'A gift card by email, for the plant they choose. Delivered by email within the hour, with a message of your own. Valid for a year in the store.', 'a green gift card with a leaf illustration', type='virtual', attributes=dict(light='', hardiness='', pot_size='', material='')),
